head.script:
//
/* Early dark mode: apply previously saved theme before first paint */
(()=>{if(localStorage.getItem('ignielplexDark')==='1'){document.documentElement.setAttribute('data-theme','dark')}})();
//

head.b:skin:
/*
<Variable name="body.background" description="Background" color="$(body.background.color)" type="background" default="$(color) none repeat scroll center center" value="$(color) url() no-repeat scroll center center /* Credit: Igniel (https://www.igniel.com) */;" hideEditor="true"/><Variable name="body.link.color" description="Link color" type="color" default="$(primary)" value="$(primary)" hideEditor="true"/><Variable name="body.text.font" description="Body Text Font" type="font" default="system-ui, -apple-system, BlinkMacSystemFont, Arial, sans-serif" value="system-ui, -apple-system, BlinkMacSystemFont, Arial, sans-serif" hideEditor="true"/><Variable name="labels.background.color" description="Labels background color" type="color" default="#fdfdfd" value="#fdfdfd" hideEditor="true"/><Variable name="posts.icons.color" description="Posts Icons Color" type="color" default="#525252" value="#525252" hideEditor="true"/><Variable name="posts.icons.color.dark" description="Posts Icons Color Dark" type="color" default="#6f6f6f" value="#6f6f6f" hideEditor="true"/><Variable name="posts.title.color" description="Posts Title Color" type="color" default="$(body.text.color)" value="$(body.text.color)" hideEditor="true"/><Variable name="tabs.color" description="Tabs color" type="color" default="#949494" value="#949494" hideEditor="true"/><Variable name="tabs.font" description="Tabs Font" type="font" default="$(body.text.font)" value="$(body.text.font)" hideEditor="true"/><Variable name="height.header" description="Header Height" type="length" default="55px" value="55px" hideEditor="true"/><Variable name="startSide" description="Side where text starts in blog language" type="automatic" default="left"/><Variable name="endSide" description="Side where text ends in blog language" type="automatic" default="right"/><Group description="Main Accent Color"><Variable name="primary" description="Main Color" type="color" default="#34579d" value="#34579d"/><Variable name="invert" description="Invert Main Color" type="color" default="#fff" value="#fff"/></Group><Group description="Background Color (Light Mode)"><Variable name="body.background.color" description="Body Background Color" type="color" default="#fdfdfd" value="#fdfdfd"/><Variable name="header.bg" description="Header Background Color" type="color" default="$(primary)" value="$(primary)"/><Variable name="posts.background.color" description="Posts Background Color" type="color" default="$(body.background.color)" value="$(body.background.color)"/><Variable name="drop.bg" description="Menu Dropdown Background Color" type="color" default="#4d95ee" value="#4d95ee"/><Variable name="feat.bg" description="Featured Widget Background Color" type="color" default="$(primary)" value="$(primary)"/><Variable name="info.bg" description="Post Info Background Color" type="color" default="#efefef" value="#efefef"/><Variable name="label.bg" description="Label Background Color" type="color" default="#efefef" value="#efefef"/><Variable name="footer.bg" description="Footer Background Color" type="color" default="transparent" value="transparent"/><Variable name="footer.br" description="Footer Border Top Color" type="color" default="#d4d4d4" value="#d4d4d4"/></Group><Group description="Background Color (Dark Mode)"><Variable name="body.background.color.dk" description="Body Background Color" type="color" default="#202124" value="#202124"/><Variable name="header.bg.dk" description="Header Background Color" type="color" default="$(primary)" value="$(primary)"/><Variable name="posts.background.color.dk" description="Posts Background Color" type="color" default="$(body.background.color.dk)" value="$(body.background.color.dk)"/><Variable name="drop.bg.dk" description="Menu Dropdown Background Color" type="color" default="#4d95ee" value="#4d95ee"/><Variable name="info.bg.dk" description="Post Info Background Color" type="color" default="#25262a" value="#25262a"/><Variable name="label.bg.dk" description="Label Background Color" type="color" default="#25262a" value="#25262a"/><Variable name="footer.bg.dk" description="Footer Background Color" type="color" default="transparent" value="transparent"/><Variable name="footer.br.dk" description="Footer Border Top Color" type="color" default="#303136" value="#303136"/></Group><Group description="Text Color (Light Mode)"><Variable name="body.text.color" description="Body Text Color" type="color" default="#232428" value="#232428"/><Variable name="header.tx" description="Header Text Color" type="color" default="$(invert)" value="$(invert)"/><Variable name="posts.text.color" description="Posts Text Color" type="color" default="#36383a"  value="#36383a"/><Variable name="link.tx" description="Link Color (Inside Article)" type="color" default="$(primary)" value="$(primary)"/><Variable name="info.tx" description="Posts Info Text Color" type="color" default="#606060" value="#606060"/><Variable name="drop.tx" description="Menu Dropdown Text Color" type="color" default="$(invert)" value="$(invert)"/><Variable name="feat.tx" description="Featured Widget Text Color" type="color" default="$(invert)" value="$(invert)"/><Variable name="feat.icon" description="Featured Widget Icon Color" type="color" default="#ffff00" value="#ffff00"/><Variable name="label.tx" description="Label Text Color" type="color" default="$(info.tx)" value="$(info.tx)"/><Variable name="footer.tx" description="Footer Text Color" type="color" default="$(info.tx)" value="$(info.tx)"/><Variable name="footer.link" description="Footer Link Color" type="color" default="$(body.text.color)" value="$(body.text.color)"/></Group><Group description="Text Color (Dark Mode)"><Variable name="body.text.color.dk" description="Body Text Color" type="color" default="#f8f9fa" value="#f8f9fa"/><Variable name="header.tx.dk" description="Header Text Color" type="color" default="$(body.text.color.dk)" value="$(body.text.color.dk)"/><Variable name="posts.text.color.dk" description="Posts Text Color" type="color" default="#cbd5e1"  value="#cbd5e1"/><Variable name="link.tx.dk" description="Link Color (Inside Article)" type="color" default="$(primary)" value="$(primary)"/><Variable name="info.tx.dk" description="Posts Info Text Color" type="color" default="#7f8893" value="#7f8893"/><Variable name="drop.tx.dk" description="Menu Dropdown Text Color" type="color" default="$(invert)" value="$(invert)"/><Variable name="label.tx.dk" description="Label Text Color" type="color" default="#7f8893" value="$(info.tx.dk)"/><Variable name="footer.tx.dk" description="Footer Text Color" type="color" default="$(info.tx.dk)" value="$(info.tx.dk)"/><Variable name="footer.link.dk" description="Footer Link Color" type="color" default="$(body.text.color.dk)" value="$(body.text.color.dk)"/></Group><Group description="Height and Width"><Variable name="width.header" description="Header Width" type="length" min="300px" max="1200px" default="$(width.main + width.aside)" value="$(width.main + width.aside)"/><Variable name="width.main" description="Width Main Post" type="length" default="680px" min="300px" max="1200px" value="680px"/><Variable name="width.aside" description="Width Aside (Sidebar)" type="length" default="300px" min="250px" max="600px" value="300px" hideEditor="true"/></Group> */
/* ======================================
TEXTRIM: Freemium Blogger Theme - Developed by Igniel (igniel.com)
======================================
Name      : TEXTRIM
Version   : 4
Released  : 10 November 2023
Updated   : 01 March 2024
Demo      : textrim.blogspot.com
License   : Personal only
Type      : Freemium (free, available in premium version)
Developer : Igniel
Country   : Indonesia
Website   : www.igniel.com
+++++++++++++++++++++++++++++++++++++++
You are free to use and modify this theme.
+++++++++++++++++++++++++++++++++++++++
FREE VERSION: NOT ALLOWED to remove the credit link at footer.
PREMIUM VERSION: ALLOWED to remove the credit link at footer.
*************************************** */
:root{--bodyBg:$(body.background.color);--bodyTx:$(body.text.color);--dropBg:$(drop.bg);--dropTx:$(drop.tx);--fontBody:'Noto Sans';--fontTitle:'Noto Sans';--footerBg:$(footer.bg);--footerBr:$(footer.br);--footerLink:$(footer.link);--footerTx:$(footer.tx);--headerBg:$(header.bg);--headerTx:$(header.tx);--infoBg:$(info.bg);--infoTx:$(info.tx);--labelBg:$(label.bg);--labelTx:$(label.tx);--postBg:$(posts.background.color);--postLink:$(link.tx);--postTx:$(posts.text.color);--gap:2rem;--bg-75:#f7f7f7;--bg-50:#efefef;--border:#d4d4d4;--syntax:#f6f6f6;--tx-s:.785em;--tx-m:.9em;--tx-75:#36383a;--tx-50:#606060;--widgetGap:3rem}
[data-theme="dark"]{--bodyBg:$(body.background.color.dk);--bodyTx:$(body.text.color.dk);--dropBg:$(drop.bg.dk);--dropTx:$(drop.tx.dk);--footerBg:$(footer.bg.dk);--footerBr:$(footer.br.dk);--footerLink:$(footer.link.dk);--footerTx:$(footer.tx.dk);--headerBg:$(header.bg.dk);--headerTx:$(header.tx.dk);--infoBg:$(info.bg.dk);--infoTx:$(info.tx.dk);--labelBg:$(label.bg.dk);--labelTx:$(label.tx.dk);--postBg:$(posts.background.color.dk);--postLink:$(link.tx.dk);--postTx:$(posts.text.color.dk);--bg-75:#232327;--bg-50:#25262a;--border:#303136;--syntax:#1d1d1d;--tx-75:#cbd5e1;--tx-50:#7f8893}
*{box-sizing:border-box}
.a,blockquote:before,.mode:before,.multi .blog-posts article:after,.menu ul ul,.multi .blog-posts article:before,.PopularPosts li:before,.PopularPosts li:after,.box.info:before,.box.success:before,.box.warning:before,.box.danger:before,.comments .avatar-image-container,.comment-actions{position:absolute}
.f,.post-body figcaption{display:flex}
.fi{position:fixed}
.g{display:grid}
.h,.hidden,.replaced,.sun,#mode:checked ~ .mode .moon,.post .post-labels span:before,.relmid:is(:empty),.thread-toggle,.comment-replies .comment-reply,.comment-replies .comment-block:before,#comment-post-message,.comment:target::before,.PopularPosts .nosnp li:before,.PopularPosts .nosnp li:after{display:none}
.m-0{margin:0}
.p-0{padding:0}
.r,blockquote,.menu .dropdown,.box.info,.box.success,.box.warning,.box.danger,.post-filter-message .search-query,.post-filter-message .search-label,.comment,.comment-replies .comment-actions{position:relative}
.s{align-self:flex-start;position:sticky;position:-webkit-sticky}
.tx-s,.comments .datetime,.label-cloud a:after,.comments-content .blog-author:after{font-size:var(--tx-s)}
.tx-m,pre code,.comment-actions{font-size:var(--tx-m)}
.tx-75,.author-name,.author-name a:not(:hover),.comments .user a:not(:hover){color:var(--tx-75)}
.tx-50,.tr-caption,.post-body figcaption,.post-share a,.Feed .item-date,.Feed .item-author,.comments .datetime,.comments .datetime a:not(:hover),.comments .user,.comment-actions a{color:var(--tx-50)}
html,body{font-size:14px;font-weight:400;line-height:1.5rem;scroll-behavior:smooth}
html,body,button,[class*="btn"],.contact-form-button,input,textarea{font-family:var(--fontBody), system-ui, -apple-system, BlinkMacSystemFont, 'Helvetica Neue', 'Roboto', 'Ubuntu', 'Segoe UI', 'Oxygen-Sans', Arial, sans-serif}
body{background-color:var(--bodyBg);margin:0;padding:0;overflow-x:hidden;word-break:break-word;text-rendering:optimizeLegibility;-webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale;-webkit-tap-highlight-color:transparent}
a,a:hover,a:link,a:visited{outline:none;text-decoration:none}
audio,canvas,progress,video{display:inline-block;vertical-align:baseline}
audio:not([controls]){display:none;height:0}
blockquote{border:1px solid var(--border);font-size:1.35em;line-height:1.5em;margin:2rem 0 2rem 1rem;padding:1em 1.25em 1em 2em}
blockquote:before{content:'';background:var(--bodyBg) url("data:image/svg+xml,%3Csvg viewBox='0 0 24 24' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M14,17H17L19,13V7H13V13H16M6,17H9L11,13V7H5V13H8L6,17Z' fill='%23606060'/%3E%3C/svg%3E") .25em center / 1.5em no-repeat;border:1px solid var(--border);height:2em;$startSide:-1rem;margin:auto;top:-.5em;width:2em}
[data-theme="dark"] blockquote:before{background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 24 24' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M14,17H17L19,13V7H13V13H16M6,17H9L11,13V7H5V13H8L6,17Z' fill='%237f8893'/%3E%3C/svg%3E")}
blockquote footer,blockquote cite{font-size:1rem;font-style:italic;line-height:normal;margin-top:1rem;text-align:$endSide}
blockquote footer:before,blockquote footer:after,blockquote cite:before,blockquote cite:after{content:'\2014';margin-top:.5rem}
blockquote footer:before,blockquote cite:before{margin-$endSide:.5rem}
blockquote footer:after,blockquote cite:after{margin-$startSide:.5rem}
button,[class*="btn"],.archive-select,.contact-form-button{border:0;outline:none}
button:not(.btn-outline):hover,.btn:hover,.btn-fill:hover,.contact-form-button:hover{opacity:.85}
kbd,mark{padding:.035em .15em}
code,kbd,mark,samp{font-family:'SFMono-Regular', 'Roboto Mono', Consolas, Menlo, Monaco, Liberation Mono, monospace, sans-serif;letter-spacing:-.35px}
code,.item-control a:hover{color:#e93f39}
details,summary,input,textarea{box-shadow:none;outline:none}
details summary::marker{display:none;font-size:0;list-style-type:none}
details summary::-webkit-details-marker{display:none;font-size:0;list-style-type:none}
details summary::-moz-list-bullet{display:none;font-size:0;list-style-type:none}
figure{margin:0}
h1,h2,h3,h4,h5,h6,.blog-title,.widget-title{font-family:var(--fontTitle), sans-serif;line-height:initial}
hr{border:0 solid var(--tx-75);border-style:dotted;border-top-width:7px;margin:2rem auto;width:2rem}
hr:before,hr:after{border:0 solid var(--tx-75);border-top-width:5px;top:-6px;width:5px}
hr:before{$startSide:-20px}
hr:after{$endSide:-20px}
iframe,textarea,video,.table,.post-body table{width:100%}
img{height:auto;max-width:100%}
input[type="text"],textarea{border:1px solid var(--border);color:#36383a;padding:0.5rem 1rem}
ins{text-decoration:none}
kbd{border:1px solid #9fa6ad;box-shadow:0 1px 1px rgba(12,13,14,0.15), inset 0 1px 0 0 var(--bodyBg);text-shadow:0 1px 0 var(--bodyBg);white-space:nowrap}
[data-theme="dark"] kbd{border-color:#3f3f3f}
.lazy{background-color:rgba(0, 0 ,0, .25);opacity:.25}
.lazyloaded{background-color:transparent;opacity:1}
.not-allowed{cursor:not-allowed}
path,polygon,ellipse,line,circle,rect{clip-rule:evenodd;fill:none;fill-rule:evenodd;stroke-linecap:round;stroke-linejoin:round;stroke-miterlimit:10;stroke-width:1.5px}
path{fill:var(--tx-50)}
select{-moz-appearance:button;-webkit-appearance:button;appearance:button}
svg{height:1.5rem;width:1.5rem}
.table{white-space:nowrap;overflow:auto}
table{border-collapse:collapse;border-spacing:0;empty-cells:hide}
td,th{padding:0}
time{cursor:help}
.widget-title{border-bottom:1px solid $(primary);display:table;font-size:1rem;margin-bottom:1.25em;margin-top:0;padding-bottom:.5em}
.header-inner,.menu-inner,.menu ul,.tool,.relmid.f,.Label li,.archive-flat li,.no-post a,.totop,.notfound,.notfound-inner,.blog-pager >*,.post-labels,.profile-link,.menu-arrow button,.menu-arrow button i{align-items:center}
.header,.menu,.wall,.menu-arrow button{background-color:var(--headerBg)}
.main-wrapper,.post-share ul{background-color:var(--postBg)}
.bg-primary,button,.btn,.btn-fill,.btn-outline:hover,.multi .blog-posts article:before,.PopularPosts li:before,.blog-pager.num a:hover,.blog-pager.num span[class]:hover,.post-body table th,#top-continue .comment-reply,.loadmore a,.label-cloud .bg-primary,.label-cloud a:hover,.archive-select:hover,.contact-form-button,.comments-content .blog-author:after{background-color:$(primary)}
.bg-75{background-color:var(--bg-75)}
.bg-50,kbd,.post-share a:hover,.box,.contact-form-widget{background-color:var(--bg-50)}
.bg-0,.btn-outline{background-color:transparent}
.round-s,input[type="text"],textarea,kbd,mark,button,[class*="btn"],.mode:before,.contact-form-button,#top-continue .comment-reply,.loadmore a,.comment .deleted,.comments-content .blog-author:after,.comments .comment-content img{border-radius:5px}
.round-m,blockquote,.post-body pre,.box,.contact-form-widget,.blogger-iframe-colorize{border-radius:7px}
.round-l,blockquote:before,.multi .blog-posts article:before,.PopularPosts li:before,.post-info-top >*:not(:first-child):before,.box.info:before,.box.success:before,.box.warning:before,.box.danger:before,.pagelist li:not(:first-child):before,.comments-content .blog-author:before,.comments .datetime:before,.comments .avatar-image-container,.comments img,.comment-actions a{border-radius:100px}
html,body,a,.post-body :is(h1, h2, h3, h4, h5){color:var(--bodyTx)}
.tx-primary,a:hover,.btn-outline,.post-body .drop,.post-labels:not(.feat-labels) a:hover,.related .noimg li::marker,.PopularPosts .nosnp li::marker,.footer a:hover,.Feed li::marker,.comment-actions .comment-reply:hover{color:$(primary)}
.header,#Header1 a,.menu a,.blog-title,.blog-title a,.menu-arrow button{color:var(--headerTx)}
.tx-invert,.tx-invert:hover,button,.btn,.btn-fill,[class*="btn"]:hover,.blog-pager.num a:hover,.blog-pager.num span[class]:hover,.post-body table th,#top-continue .comment-reply,.loadmore a,.label-cloud a:hover,.archive-select:hover,.contact-form-button,.comments-content .blog-author:after,input.search-input{color:$(invert)}
button:not(.btn-outline) a,button a:hover,button:hover a{color:$(invert) !important;text-decoration:none !important}
.pointer,button,[class*="btn"],.menu li,.contact-form-button,.contact-form-error-message,.contact-form-error-message-with-border,.contact-form-success-message{cursor:pointer}
button,[class*="btn"],.menu li,.dropdown span:after,.blog-pager.num a,.post-info-top >*:not(:first-child):before,.pagelist li,.pagelist li:not(:first-child):before,.contact-form-button,.comments .datetime:before,#top-continue .comment-reply,.loadmore a{display:inline-block}
.b,.post-filter-message .search-query,.post-filter-message .search-label,.blog-pager:not(.num) >*,.comments .user{font-weight:bold}
.share-label:hover path,.post-share a:hover path,#share:checked ~ .share-label path,.social a:hover path,.Label path,.BlogArchive path,.blog-pager:not(.num) a:hover path,.profile-link path,.post-location path{fill:$(primary)}
button:not([class]) path,.btn-fill path,.feat-icon path,.search-icon path{fill:$(invert)}
.post-info-text,.label-cloud li,.no-post-home,.totop,.notfound,.notfound-inner,.center figcaption,.profile-link,.menu-arrow button i{justify-content:center}
.menu-inner,.blog-pager,.post-share ul,.post .post-info{justify-content:space-between}
.tool,.profile-avatar,.author-avatar{line-height:0}
.related-thumbnail img,.relmid-thumbnail img{object-fit:cover}
.center{margin-$startSide:auto;margin-$endSide:auto;text-align:center}
.menu ul,.breadcrumb,.pagelist ul,.post-share ul,.related ul:not(.noimg),.comments ol,.Label ul,.PopularPosts ul,.BlogArchive ul,.Profile .team,.social ul,.BlogList ul,.BlogList li{list-style-type:none;margin:0;padding:0}
html,body,a,button,[class*="btn"],input[type="text"],textarea,kbd,path,blockquote,blockquote:before,.bg-50,.bg-75,.feat-info,.post-body pre,.post-labels a,.blog-pager a,.blog-pager.num span,.blog-pager .left,.post-author,.footer,.footer-inner,.post-desc,.post-filter-message,.post-body table th,.post-body table td,.contact-form-widget,.box,.comment-actions a,.comment-block:before,.comment-replies ol li:after,.comments .avatar-image-container,.comment-msg,.label-cloud a,.archive-select,.contact-form-button,.totop,.lazyloaded,input.search-input{transition:all .3s;-webkit-transition:all .3s}
.header{padding:var(--gap) 0 var(--gap)}
.header,.menu{color:var(--headerTx);z-index:2}
.blog-title{font-size:1.5rem;margin:0;max-width:35vw;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.header-inner{gap:3rem;padding:0 calc(var(--gap) - .5rem)}
.header-inner,.menu-inner{margin:auto;max-width:calc($(width.header) + calc(2 * var(--gap)))}
#Header1 img{height:100%;max-height:100px;max-width:300px;vertical-align:middle;width:auto}
#Header1{background-position:$startSide center;background-repeat:no-repeat;background-size:contain}
.tool{flex:1 0 auto;gap:1.5rem}
.search{width:100%}
.search-icon{bottom:0;line-height:calc($(height.header) - 15px);margin:auto;$startSide:1rem;top:0;z-index:2}
.search-icon svg{height:1rem;vertical-align:-1px;width:1rem}
input.search-input{border-color:transparent;height:calc($(height.header) - 15px);padding-$startSide:2.75rem;padding-$endSide:1.5rem;width:100%}
input.search-input:active,input.search-input:focus,[data-theme="dark"] input.search-input:active,[data-theme="dark"] input.search-input:focus{background-color:$(invert);border:0;color:#36383a}
input.search-input:active ~ .search-icon path,input.search-input:focus ~ .search-icon path,[data-theme="dark"] input.search-input:active ~ .search-icon path,[data-theme="dark"] input.search-input:focus ~ .search-icon path{fill:#303136}
input.search-input,.feat-info,.mode:before,.menu a:hover,.menu .dropdown:hover,.menu-inner .open,.menu-arrow button:hover i{background-color:rgba(255, 255, 255, .075)}
[data-theme="dark"] input.search-input,[data-theme="dark"] .feat-info,[data-theme="dark"] .mode:before,[data-theme="dark"] .menu a:hover,[data-theme="dark"] .menu .dropdown:hover,[data-theme="dark"] .menu-inner .open,[data-theme="dark"] .menu-arrow button:hover i{background-color:rgba(0, 0, 0, .15)}
input.search-input::placeholder{color:$(invert);opacity:.5}
.mode svg{height:1.75rem;width:1.75rem}
.mode path,.menu path{fill:var(--headerTx)}
#mode:checked ~ .mode .sun{display:block}
.mode:before,.menu-arrow button i{transition:background-color .3s}
.mode:before{content:'';bottom:0;height:calc($(height.header) - 15px);margin:auto;$startSide:-.5rem;top:0;width:calc(100% + 1rem)}
.menu{gap:4rem;top:0}
.menu nav{height:$(height.header);max-width:100%}
.menu ul:first-child{overflow-x:auto;overflow-y:hidden;white-space:nowrap}
.menu ul[style]::-webkit-scrollbar{height:0}
.menu-inner{padding:0 calc(var(--gap) - .5rem) 0 .5rem}
.menu-inner .open{position:relative;z-index:1}
.menu li{white-space:nowrap}
.menu a,.menu span{line-height:$(height.header);display:block;padding:0 1rem}
.menu .dropdown ul{background-color:var(--dropBg);border-radius:0 0 7px 7px;color:var(--dropTx);$startSide:0;min-width:100%;opacity:0;padding:0;top:$(height.header);transform:translateY(-1rem);-webkit-transform:translateY(-1rem);transition:all .3s ease-in-out 0s;-webkit-transition:all .3s ease-in-out 0s;visibility:hidden}
.menu-inner .dropdown.open ul{opacity:1;visibility:visible;transform:translateY(0px);-webkit-transform:translateY(0px)}
.menu .dropdown li{display:block}
.menu .dropdown a{line-height:40px}
.menu .dropdown ul,.menu .dropdown li a{color:var(--dropTx);overflow:hidden}
.dropdown span:after{content:'\203A';margin-$startSide:.75rem;transform:rotate(90deg);-webkit-transform:rotate(90deg);transition:transform .2s linear;-webkit-transition:transform .2s linear}
.menu-inner .dropdown.open span:after{transform:rotate(270deg);-webkit-transform:rotate(270deg)}
.menu-arrow button{border:0;border-radius:0;bottom:0;height:100%;margin:0;padding:0;top:0;width:4rem}
.menu-arrow button:hover{opacity:1}
.menu-arrow button i{height:1rem;line-height:0;padding:1rem;width:1rem}
.menu-next{justify-content:flex-end;$endSide:-1.5rem}
.menu-next i{margin-$startSide:auto}
.menu-prev{justify-content:flex-start;$startSide:-1.5rem}
.menu-prev i{margin-$endSide:auto}
.wall{height:30%;max-height:250px;width:100%}
.billboard{margin:0 auto}
.billboard .widget-content{margin-bottom:var(--widgetGap)}
.mains{margin:var(--gap) var(--gap) auto}
.main-wrapper{margin:0 auto;padding:var(--widgetGap);transition:background-color .3s}
.main-wrapper,.footer-inner,.billboard{max-width:calc($(width.main + width.aside) + calc(3 * var(--widgetGap)))}
.main-inner{column-gap:var(--widgetGap);grid-template-areas:'main aside' 'main sticky';grid-template-columns:minmax(auto, 1fr) minmax(auto, $(width.aside));grid-template-rows:auto 1fr}
.main{grid-area:main;max-width:$(width.main)}
.page .main{max-width:100%}
.main .widget:not(:last-child){margin-bottom:var(--gap)}
.aside{grid-area:aside}
.aside_sticky{grid-area:sticky}
.aside,.aside_sticky{top:calc($(height.header) + 20px);max-width:$(width.aside)}
#HTML8 .widget-content >*{margin:auto;text-align:center;width:100%}
.blog-posts{gap:var(--widgetGap)}
.multi .blog-posts article{padding-$startSide:2rem}
.multi .blog-posts article:before{height:13px;width:13px}
.multi .blog-posts article:before,.PopularPosts li:before{$startSide:0;z-index:1}
.multi .blog-posts article:after{$startSide:6px}
.multi .blog-posts article:after,.PopularPosts li:after{background-color:var(--border);height:calc(100% - 4px);width:1px}
.multi .blog-posts article:before,.multi .blog-posts article:after,.PopularPosts li:before,.PopularPosts li:after{content:'';margin:auto;top:7px;transition:background-color .3s}
.post-title{font-size:1.25rem;margin:0}
.single .entry-title{font-size:1.85rem;line-height:1.5em;margin:.5em 0 .75em;padding:0}
.single.page .entry-title{margin-top:0}
.post-info,.feat-info{transition:background-color .2s}
.multi .post-info{margin-top:1.25rem;padding:.75em 1em}
.multi .post-info:not(.feat-info){background-color:var(--infoBg)}
.post .post-info{border-bottom:1px solid var(--border);gap:2rem;overflow:unset;padding-bottom:1rem;transition:border-color .2s}
.multi .post-info > span:not(:first-child):before{content:'\2014';margin:0 3px}
.post-inner,.feat-content{margin-top:.75rem}
.post .post-infos{gap:1rem;white-space:normal}
.post-share{margin-top:.25rem}
.multi .post-location:after,.post-info-bottom >*:not(:first-child):before{content:'\2012';margin:0 .15em}
.post-location svg{height:1rem;margin-$endSide:.15em;vertical-align:-2px;width:1rem}
.multi .post-location svg{margin-$endSide:.25em;vertical-align:-1px}
.multi .post-location:after{margin-$startSide:.5em}
.post .post-info-bottom >*:not(:first-child):before{margin-$endSide:.35em}
.post-info-text{flex-direction:column;line-height:1.75rem}
.post-info-top >*:not(:first-child):before,.comments .datetime:before{background-color:var(--tx-50);margin:0 4px}
.post-info-top >*:not(:first-child):before,.comments .datetime:before,.pagelist li:not(:first-child):before{content:'';height:4px;vertical-align:middle;width:4px}
.post-info:not(.feat-info),.post-info:not(.feat-info) a:not(.tx-primary, :hover){color:var(--infoTx)}
.post-inner,.feat-content{text-align:justify;word-break:break-word}
.post-labels{flex-wrap:wrap;gap:.75rem;margin-top:.75rem}
.post .post-labels{gap:.75rem;margin-top:var(--gap)}
.post-labels a,.comment-actions a{line-height:normal;padding:.65em .85em}
.post-labels a,.post-labels span,.comment-actions .comment-reply{border-color:var(--border)}
input[type="text"]:active,input[type="text"]:focus,textarea[type="text"]:active,textarea[type="text"]:focus,.post-labels:not(.feat-labels) a:hover,.comment-actions .comment-reply:hover{border-color:$(primary)}
.blog-pager.num a,.label-cloud a,.archive-select{background-color:var(--labelBg)}
.blog-pager.num a,.label-cloud a,.archive-select{color:var(--labelTx)}
.post-desc{border-bottom:1px solid var(--border);font-style:italic;padding:1rem 0}
.single .entry-content :not(.post-labels) a:not([class*="btn"]),.breadcrumb a:not(:hover){color:var(--postLink)}
.entry-content a:not([class*="btn"]):hover,.multi .post-location a:hover,.post-info a:hover,.breadcrumb a:hover{text-decoration:underline}
.entry-content,.post-title,.post-desc,.populer-snippet,.pagelist{line-height:1.6em}
.single .entry-content{line-height:1.825em;margin-top:1.5em}
.single .entry-content,.post-body pre code,.comment-content,.comment-body{color:var(--postTx);font-size:1.175rem;word-break:break-word}
.blog-pager svg{height:1.25rem;width:1.25rem}
.blog-pager span{padding-$startSide:0;padding-$endSide:0}
.blog-pager:not(.num) a,.blog-pager:not(.num) span{margin-bottom:.5em}
.blog-pager,.related,.comments,.comments ol > li{margin-top:var(--widgetGap)}
.blog-pager.num{gap:2rem}
.blog-pager .left{height:fit-content;white-space:nowrap}
.blog-pager .right{flex-wrap:wrap;gap:.5rem}
.blog-pager .left,.blog-pager.num span,.blog-pager.num a{padding:.5em 1em}
.blog-pager .f{gap:.5em}
.breadcrumb{flex-wrap:wrap}
.breadcrumb li:not(:last-of-type):after{content:'/';margin:0 .5rem 0 .35rem}
.post-body figure,.post-body table,.post-body .table,.box,audio,canvas,progress,video{margin-bottom:1.5em}
.post-body pre{background-color:var(--syntax);hyphens:none;line-height:1.25em;max-height:300px;overflow:auto;padding:.75em;tab-size:2;white-space:pre;word-break:normal;word-wrap:break-word}
.post-body pre code{direction:ltr;font-size:.85em;letter-spacing:0;user-select:text;-webkit-user-select:text;-khtml-user-select:text;-moz-user-select:text;-ms-user-select:text}
button,[class*="btn"],.contact-form-button{border:1px solid $(primary);font-size:inherit;padding:.75em 1em;margin:.25em}
.post-body ol[type="a"],.post-body ol[type="A"] ol[type="a"]{list-style-type:lower-alpha}
.post-body ol[type="A"]{list-style-type:upper-alpha}
.post-body .drop{font-size:3.5em;float:$startSide;line-height:1em;padding-$endSide:.1em}
.atop:not(:empty),.abottom:not(:empty){margin-top:1.5em}
.amiddle{margin:1.5em 0}
.post-body .table table{margin:0}
.tr-caption,.post-body figcaption{font-size:1rem;line-height:normal}
.post-body figcaption{margin-top:.5em}
.post-body figcaption:before{content:'';align-self:flex-start;background:url("data:image/svg+xml,%3Csvg viewBox='0 0 512 512' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M256 512A256 256 0 1 0 256 0a256 256 0 1 0 0 512zM216 336h24V272H216c-13.3 0-24-10.7-24-24s10.7-24 24-24h48c13.3 0 24 10.7 24 24v88h8c13.3 0 24 10.7 24 24s-10.7 24-24 24H216c-13.3 0-24-10.7-24-24s10.7-24 24-24zm40-208a32 32 0 1 1 0 64 32 32 0 1 1 0-64z' fill='%23606060'/%3E%3C/svg%3E") left center / 1.25em no-repeat;flex-shrink:0;height:1.25em;margin-$endSide:.5em;width:1.25em}
[date-theme="dark"] .post-body figcaption:before{background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 512 512' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M256 512A256 256 0 1 0 256 0a256 256 0 1 0 0 512zM216 336h24V272H216c-13.3 0-24-10.7-24-24s10.7-24 24-24h48c13.3 0 24 10.7 24 24v88h8c13.3 0 24 10.7 24 24s-10.7 24-24 24H216c-13.3 0-24-10.7-24-24s10.7-24 24-24zm40-208a32 32 0 1 1 0 64 32 32 0 1 1 0-64z' fill='%237f8893'/%3E%3C/svg%3E")}
.post-body table th:not(:last-child){border-$endSide:1px solid var(--bodyBg)}
.post-body table th,.post-body table td{padding:.75em;word-break:normal}
.post-body table td{border:1px solid rgba(0, 0, 0, .1)}
[data-theme="dark"] .post-body table td{border:1px solid rgba(106, 111, 188, .15)}
.post-body table tr:nth-child(even){background-color:rgba(0, 0, 0, .035)}
[data-theme="dark"] .post-body table tr:nth-child(even){background-color:rgba(106, 111, 188, .035)}
.post-body .separator a{margin:0 !important}
.box{border:1px solid var(--border);padding:.75em 1.25em}
.box a{text-decoration:underline}
.box.info,.box.success,.box.warning,.box.danger{color:initial;margin-$startSide:.5em;margin-top:2em;padding-$startSide:1.75em}
.box.info:before,.box.success:before,.box.warning:before,.box.danger:before{content:'';background-position:center;background-repeat:no-repeat;background-size:.85em;$endSide:0;height:2em;$startSide:-1em;top:-.5em;width:2em}
.box.info{background-color:#f0f5fd;border-color:#dae5f6}
.box.info:before{background-color:#3578e5;background-size:.75em;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 384 512' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M192 32c17.7 0 32 14.3 32 32V199.5l111.5-66.9c15.2-9.1 34.8-4.2 43.9 11s4.2 34.8-11 43.9L254.2 256l114.3 68.6c15.2 9.1 20.1 28.7 11 43.9s-28.7 20.1-43.9 11L224 312.5V448c0 17.7-14.3 32-32 32s-32-14.3-32-32V312.5L48.5 379.4c-15.2 9.1-34.8 4.2-43.9-11s-4.2-34.8 11-43.9L129.8 256 15.5 187.4c-15.2-9.1-20.1-28.7-11-43.9s28.7-20.1 43.9-11L160 199.5V64c0-17.7 14.3-32 32-32z' fill='%23fff'/%3E%3C/svg%3E")}
.box.success{background-color:#f0fdf6;border-color:#dff6da}
.box.success:before{background-color:#42b72a;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 448 512' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M438.6 105.4c12.5 12.5 12.5 32.8 0 45.3l-256 256c-12.5 12.5-32.8 12.5-45.3 0l-128-128c-12.5-12.5-12.5-32.8 0-45.3s32.8-12.5 45.3 0L160 338.7 393.4 105.4c12.5-12.5 32.8-12.5 45.3 0z' fill='%23fff'/%3E%3C/svg%3E")}
.box.warning{background-color:#fcfdf0;border-color:#f6f1da}
.box.warning:before{background-color:#f7bb3b;background-size:.385em;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 192 512' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M48 80a48 48 0 1 1 96 0A48 48 0 1 1 48 80zM0 224c0-17.7 14.3-32 32-32H96c17.7 0 32 14.3 32 32V448h32c17.7 0 32 14.3 32 32s-14.3 32-32 32H32c-17.7 0-32-14.3-32-32s14.3-32 32-32H64V256H32c-17.7 0-32-14.3-32-32z' fill='%23fff'/%3E%3C/svg%3E")}
.box.danger{background-color:#fdf0f0;border-color:#fae1e1}
.box.danger:before{background-color:#e93f39;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 448 512' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M349.4 44.6c5.9-13.7 1.5-29.7-10.6-38.5s-28.6-8-39.9 1.8l-256 224c-10 8.8-13.6 22.9-8.9 35.3S50.7 288 64 288H175.5L98.6 467.4c-5.9 13.7-1.5 29.7 10.6 38.5s28.6 8 39.9-1.8l256-224c10-8.8 13.6-22.9 8.9-35.3s-16.6-20.7-30-20.7H272.5L349.4 44.6z' fill='%23fff'/%3E%3C/svg%3E")}
.box ul,.box ol{margin:0;padding-inline-start:1.25em}
.post-share ul{border:1px solid var(--border);$endSide:0;max-height:0;opacity:0;overflow:hidden;top:2.5rem;transition:max-height .2s, opacity .7s, visibility .7s, background-color .2s, border-color .2s;-webkit-transition:max-height .2s, opacity .7s, visibility .7s, background-color .2s, border-color .2s;visibility:hidden}
#share:checked ~ ul{max-height:100vh;opacity:1;transition:max-height .5s, opacity .1s, visibility .1s, background-color .2s, border-color .2s;-webkit-transition:max-height .5s, opacity .1s, visibility .1s, background-color .2s, border-color .2s;visibility:visible;z-index:1}
.post-share li{flex:1 0 auto}
.post-share a{gap:.75rem;padding:.85rem 1.25rem;white-space:nowrap}
.post-share a:hover{text-decoration:none}
.related-inner{margin-top:var(--gap)}
.related ul{gap:2rem;grid-template-columns:repeat(2, 1fr)}
.related li{column-gap:1rem}
.related .noimg li,.PopularPosts .nosnp li{list-style-type:disc}
.related-thumbnail,.relmid-thumbnail{flex-shrink:0;line-height:0}
.related-thumbnail img,.relmid-thumbnail img{height:72px;width:72px}
.related-thumbnail svg,.relmid-thumbnail svg{height:2.5rem;width:2.5rem}
.related .noimg{gap:1.5rem 3rem;margin:0;padding:0}
.related .noimg,.PopularPosts .nosnp{margin-inline-start:1.35rem}
.relmid:not(:empty){border-top:1px solid var(--border);border-bottom:1px solid var(--border);line-height:1.65em;margin:1em 0;padding:1em 0;transition:background-color .3s}
.relmid strong{margin-$endSide:.35em;white-space:nowrap}
.relmid-thumbnail{margin-$endSide:1rem}
.relmid-thumbnail img{filter:contrast(.85);-webkit-filter:contrast(.85)}
.aside .widget-content,.aside_sticky .widget-content,.contact-form-widget{margin-bottom:var(--widgetGap)}
.footer{background-color:var(--footerBg);color:var(--footerTx)}
.footer a{color:var(--footerLink)}
.footer-inner{border-top:1px solid var(--footerBr);gap:1rem;justify-content:stretch;margin:0 auto;padding:var(--gap);width:100%}
.footer-inner [class*="footer"]{column-gap:1.5rem;grid-template-columns:repeat(2, 1fr)}
.pagelist li:not(:first-child):before{background-color:var(--footerTx);margin:0 7px}
.social,.credit{text-align:$endSide}
.social svg{height:1.5rem;width:1.5rem}
.social path{fill:var(--footerTx)}
.social ul{gap:1rem;justify-content:flex-end}
.post-author{border-top:1px solid var(--border);gap:1rem;margin-top:var(--gap);padding-top:var(--gap)}
.author-avatar img{max-width:50px}
.author-desc{margin-top:.5em}
.FeaturedPost .widget-title{border-bottom:1px solid $(feat.icon);margin-bottom:1.5em;padding-bottom:.75em}
.FeaturedPost .widget-title,.feat-title a:hover{color:$(feat.icon)}
.FeaturedPost .widget-content{margin-bottom:var(--widgetGap);padding:1.25rem 1.5rem}
.feat-icon svg{height:1rem;width:1rem}
.feat-title{font-size:1.5rem}
.feat-content{opacity:.75}
.feat-labels{border-color:$(feat.tx)}
.feat-labels a{border-color:$(feat.tx)}
.feat-labels a:hover,.feat-info a:hover{border-color:$(feat.icon);color:$(feat.icon)}
.feat-labels a,.post-labels a,.comment-actions .comment-reply{border-width:1px;border-style:solid}
.FeaturedPost .widget-content,.feat-title a,.feat-content,.feat-labels a:not(:hover),.feat-info a:not(:hover){color:$(feat.tx)}
.profile-location svg{height:1rem;margin-$endSide:.25em;vertical-align:-1px;width:1em}
.profile-location,.profile-text{margin-top:.5rem}
.profile-name,.profile-link{margin-top:.75rem}
.profile-link{gap:.5em}
.profile-link svg{height:1rem;width:1rem}
.Profile .team{flex-wrap:wrap;gap:.5rem}
.Label svg{height:1.25rem;width:1.25rem}
.Label svg,.label-list .label-count,.BlogArchive svg,.archive-flat .label-count,.bloglist-icon{flex-shrink:0}
.Label li,.label-cloud ul,.archive-flat li{gap:.5rem}
.label-list ul,.archive-flat ul{gap:.75rem 2.5rem;grid-template-columns:repeat(2, 1fr)}
.label-list li{white-space:nowrap}
.label-list li,.label-list a,.label-list span,.archive-flat li,.archive-flat a,.archive-flat span{overflow:hidden;white-space:nowrap}
.label-list a,.label-list span,.archive-flat a,.archive-flat span{text-overflow:ellipsis}
.label-list .label-count,.archive-flat .label-count{margin-$startSide:auto}
.label-list .label-count:before{content:'('}
.label-list .label-count:after{content:')'}
.label-cloud ul{flex-wrap:wrap}
.label-cloud li{flex:1 0 auto;max-width:100%}
.label-cloud li >*{flex:1 0 100%;overflow:hidden;padding:.5rem .75rem;text-overflow:ellipsis;white-space:nowrap;width:100%}
.label-cloud li >*[data-count]:after{content:'('attr(data-count)')';margin-$startSide:.5em}
.label-list .remaining-items{margin-top:.75rem}
.label-cloud .remaining-items{margin-top:.5rem}
.show-more,.show-less{margin-top:1.25em}
.PopularPosts ul{gap:2rem;grid-template-columns:repeat(1, 1fr)}
.popular-title{margin-bottom:.5rem}
.PopularPosts .nosnp{gap:1rem}
.PopularPosts li{padding-$startSide:1.5rem}
.PopularPosts .nosnp li{padding-$startSide:0}
.PopularPosts li:before{height:9px;width:9px}
.PopularPosts li:after{$startSide:4px}
.BlogArchive{line-height:1.75rem}
.hierarchy-content.archive-hierarchy{margin-$startSide:1rem}
.archive-select{padding:.75rem;width:100%}
.BlogList li:not(:last-child){margin-bottom:1rem}
.bloglist-container{gap:.75rem}
.bloglist-item{display:inline-block;line-height:1.25rem;margin-top:0.25rem}
.contact-form-widget{padding:.25rem 1.25rem}
[class*="contact-form"]:not(img){width:100%}
.contact-form-widget input:not([class])[type="text"]:focus,.contact-form-widget textarea:focus{border:1px solid $(primary)}
.contact-form-error-message img,.contact-form-error-message-with-border img,.contact-form-success-message img{margin-$startSide:.5rem}
.Feed ul{padding-$startSide:1.35rem}
.Feed li:not(:last-child){margin-bottom:1rem}
.no-post svg,.notfound svg{margin-$endSide:.5rem}
.no-post-home{margin-top:1.5rem}
.post-filter-message{border:1px solid var(--border);margin-bottom:var(--gap);padding:1rem 1.25rem}
.post-filter-message .search-query,.post-filter-message .search-label{text-transform:none;font-style:italic}
.post-filter-message .search-query:after,.post-filter-message .search-label:after{content:'';border-bottom:2px solid $(primary);position:absolute;$startSide:0;bottom:-7px;width:100%}
.notfound{height:100vh;width:100vw}
.notfound-inner{flex-direction:column;flex-wrap:wrap;padding:2rem}
.notfound h2{font-size:3.5rem;margin-bottom:1rem}
.notfound-home{margin-top:1.5rem}
.totop{border:0;bottom:var(--gap);$endSide:calc(2 * var(--gap));height:3rem;margin:0;opacity:0;padding:0;visibility:hidden;width:3rem}
.totop.show{opacity:1;visibility:visible}
.totop svg{height:2rem;vertical-align:-3px;width:2rem}
.comment-msg{margin-bottom:1rem;padding:1rem 1.25rem}
.comments .widget-title,#top-continue{text-transform:capitalize}
.comments .user,.read-time i,.menu-arrow button i{font-style:normal}
.comments .datetime{margin-$startSide:.25em}
.comment-block:before{border-$startSide:1px solid var(--border);bottom:35px;height:auto;opacity:1;$startSide:18px;top:43px}
.comment-replies ol li:after{border-top:1px solid var(--border);bottom:0;height:auto;opacity:1;$startSide:-32px;top:2rem;width:23px}
.comment-block:before,.comment-replies ol li:after{content:'';margin-top:0;position:absolute;visibility:visible}
.comment-block,.comment-replies{margin-$startSide:50px}
