.comment{padding-bottom:2.5rem}
.comment .comment{padding-bottom:0;padding-top:.75rem}
.comments ol > li:first-child{margin-top:1.5rem}
.comment-header{margin-bottom:.5rem}
.comment-content{margin:0}
.comment-content,.comment-body{line-height:1.5em}
.comments-content .blog-author:after{content:'Author';font-weight:normal;margin-$startSide:.5em;padding:.25em .5em;vertical-align:1px}
.comment-replies{margin-top:1rem}
.comment-actions{bottom:0;$startSide:0}
.comment-replies .comment-actions{display:block;margin-top:.75rem}
.comment-replies .comment-actions a{padding:0}
.comment-actions >*:not(:last-child){margin-$endSide:.5rem;margin-$startSide:-.75rem}
.comment-replybox-thread{margin-top:2rem}
.comment-replybox-single{margin:1rem 0 .5rem 50px;width:calc(100% - 50px)}
.blogger-iframe-colorize{background-color:$(body.background.color);transition:height .2s, padding .2s;-webkit-transition:height .2s, padding .2s}
[data-theme="dark"] .blogger-iframe-colorize{padding:.25rem .5rem}
.comment .deleted,.comments .deleted{background-color:#ffe6e6;color:#36383a;padding:0.5em 0.75em;margin:1em 0}
#top-continue,.loadmore{margin:1.5rem 0;text-align:center}
#top-continue .comment-reply,.loadmore a{padding:.75rem 1rem;transition:opacity .2s;-webkit-transition:opacity .2s}
#top-continue .comment-reply:hover,.loadmore a:hover{opacity:.85}
@media screen and (max-width:1200px){
  .menu-inner{padding:0 calc(var(--gap) - 1rem)}
  .menu-next{$endSide:0}
  .menu-next i{margin-$endSide:1rem}
  .menu-prev{$startSide:0}
  .menu-prev i{margin-$startSide:1rem}
  .FeaturedPost .article{grid-template-columns:minmax(auto, 350px) minmax(0, auto)}
}
@media screen and (max-width:1024px){
  .blog-title{max-width:40vw}
  .totop{$endSide:var(--gap)}
}
@media screen and (max-width:950px){
  .main-wrapper{padding:var(--gap)}
  .PopularPosts :not(.noimg){gap:1rem 3rem;grid-template-columns:repeat(2, 1fr)}
}
@media screen and (max-width:900px){
  .main-inner{display:block}
  .main{max-width:100%}
  .blog-posts{grid-template-columns:1fr 1fr}
  .aside,.aside_sticky{margin-top:3rem;position:static;max-width:100%}
  .relmid:not(:empty){border-radius:0;margin-$startSide:calc(-1 * calc(2 * var(--gap)));padding-$endSide:calc(2 * var(--gap));padding-$startSide:calc(2 * var(--gap));width:calc(100% + calc(4 * var(--gap)))}
}
@media screen and (max-width:768px){
  .mains{margin:auto auto}
  .main-wrapper{border-top-$endSide-radius:0;border-top-$startSide-radius:0}
  .header{padding-bottom:1rem}
  .menu-inner{gap:3rem;padding:0 calc(var(--gap) - 2rem)}
}
@media screen and (max-width:680px){
  .article,.FeaturedPost .article{grid-template-columns:minmax(50%, 1fr) minmax(0, auto)}
}
@media screen and (max-width:640px){
  .blog-posts{grid-template-columns:1fr}
  .footer-inner{gap:1.5rem}
  .footer-inner [class*="footer"]{column-gap:0;grid-template-columns:repeat(1, 1fr);row-gap:0}
  .footer-inner [class*="footer"],.credit{text-align:center}
  .footer-inner .footer-top{row-gap:1.5rem}
  .footer-inner .footer-bottom{row-gap:.35rem}
  .social ul{justify-content:center}
}
@media screen and (max-width:568px){
  :root{--gap:1.5rem}
  html,body{font-size:13.5px}
  .header-inner{display:block;padding:0 var(--gap);text-align:center}
  #Header1{margin-bottom:var(--gap)}
  .blog-title{max-width:100%}
  .multi .blog-posts article{padding-$startSide:1.5rem}
  .multi .blog-posts article:after{height:calc(100% - 6px);$startSide:0}
  .multi .blog-posts article:before{height:9px;$startSide:-4px;width:9px}
  .single .entry-title{font-size:1.65rem}
  .related ul{grid-template-columns:repeat(1, 1fr)}
  .related .noimg{gap:1rem}
  .PopularPosts :not(.noimg){grid-template-columns:repeat(1, 1fr)}
}
@media screen and (max-width:480px){
  :root{--gap:1.25rem}
  html,body{font-size:13px}
}
@media screen and (max-width:360px){
  html,body{font-size:12px}
  .single .entry-title{font-size:1.75rem}
}

b:if.b:template-skin:
body#layout{max-width:90%;padding:90px 20px 20px}
body#layout:before,body#layout:after{color:#34579d;font-family:Arial, sans-serif;position:absolute}
body#layout:before{content:'Textrim v4';border:1px solid #34579d;border-radius:25px;font-size:24px;left:27px;padding:7px 15px;top:27px}
body#layout:after{content:'Official demo and download: textrim.blogspot.com';font-size:18px;right:95px;top:45px;visibility:visible}
body#layout div.section,body#layout .mains{margin-bottom:20px;margin-left:0;margin-right:0;padding:15px 25px}
body#layout .section h4,body#layout .mains:before{font-size:18px;letter-spacing:.5px;margin:0 0 7px;text-transform:uppercase}
body#layout .widget-content{margin-bottom:7px}
body#layout .add_widget{border-color:#b4b4b4}
body#layout div.section,body#layout .widget-content,body#layout .add_widget,body#layout .mains{border-radius:7px}
body#layout .editlink.icon{z-index:99}
body#layout:before,body#layout:after,body#layout .mains:before,body#layout .header h4,body#layout .menu h4,body#layout .footer-top,body#layout .footer-bottom{color:#34579d}
body#layout #configuration{background-color:#34579d;color:#fff;display:block}
body#layout .mains{background-color:#f8f8f8;border:1px solid #ccc;padding-top:60px;position:relative}
body#layout .mains:before{content:'Main Body';font-family:Arial, sans-serif;left:27px;position:absolute;top:20px}
body#layout .main{width:56%}
body#layout .aside,body#layout .aside_sticky{max-width:40%}
body#layout .aside_sticky{float:right}
body#layout .s{position:static}
body#layout .footer-bottom:after{content:'CREDIT LINK can be removed or modified via HTML if you have purchased the premium version.';background-color:#34579d;border-radius:5px;color:#fff;display:block;font-family:Arial, sans-serif;font-size:14px;margin-top:20px;padding:15px}
body#layout #HTML4,body#layout #HTML1 .layout-widget-description,body#layout #HTML2 .layout-widget-description{display:none}
body#layout #HTML6{width:100%}
body#layout #HTML7 .widget-content,body#layout #HTML8 .widget-content,body#layout #HTML9 .widget-content,body#layout #HTML10 .widget-content{background-color:#b6d8f5;color:#222}
body#layout #configuration,body#layout .header-inner,body#layout .mains,body#layout .footer .section{display:block}
body#layout #configuration,body#layout .mains,body#layout .footer .section{overflow:auto}
body#layout #HTML1,body#layout #HTML2,body#layout #HTML5,body#layout .main,body#layout .aside,body#layout #PageList1{float:left}
body#layout #HTML1,body#layout #HTML2,body#layout #HTML5,body#layout #PageList1{width:48%}
body#layout #HTML1,body#layout .main,body#layout #PageList1{margin-right:18px}
@media screen and (max-width:600px){
  body#layout{padding-top:100px}
  body#layout:before{font-size:18px;top:17px}
  body#layout:after{font-size:14px;left:27px;right:unset;top:70px}
  body#layout #configuration,body#layout .header-inner,body#layout .footer-inner{display:table}
  body#layout #HTML1,body#layout #HTML2,body#layout #HTML5,body#layout .main,body#layout .aside,body#layout .aside_sticky,body#layout #PageList1,body#layout #HTML6,body#layout #HTML6{float:none;width:100%}
  body#layout #HTML1,body#layout #HTML5,body#layout main,body#layout #PageList1{margin-right:0}
}

